import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load and prepare texture
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create plane geometry with card aspect ratio
  const geometry = new THREE.PlaneGeometry(1.6, 1);

  // Create material
  const material = new THREE.MeshBasicNodeMaterial({
    map: texture,
    side: THREE.DoubleSide
  });

  // Create and position plane mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(
    config.scenePosition.x,
    config.scenePosition.y,
    config.scenePosition.z
  );
  mesh.rotation.order = 'XYZ';
  mesh.rotation.set(
    config.rotation.x,
    config.rotation.y,
    config.rotation.z
  );
  mesh.scale.set(
    config.scale.x,
    config.scale.y,
    config.scale.z
  );
  group.add(mesh);

  // Render text content via font atlas
  if (config.textContent && config.textContent.length > 0) {
    const textSpec = config.textContent[0];
    const textMesh = ctx.fontAtlas.createTextMesh(textSpec.text, {
      fontSize: textSpec.size,
      fontFamily: textSpec.fontFamily || 'Lora',
      fontWeight: textSpec.weight,
      color: config.colors.ink
    });
    textMesh.position.z = 0.01; // Slightly in front of plane
    group.add(textMesh);
  }

  // Cleanup handler
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
    gsap.killTweensOf(group);
  };

  return group;
}
